import React, { useState } from "react";
import MonitoringWidget from "../components/MonitoringWidget";
import MLWidget from "../components/MLWidget";

const AdminDashboard = () => {
  const [darkMode, setDarkMode] = useState(false);

  // Mock server logs and error rates
  const serverLogs = [
    "Server started successfully",
    "Database connection established",
    "API response time: 120ms",
    "Warning: High memory usage detected",
  ];

  const errorRate = "2.5%"; // Example error rate

  const handleToggleDarkMode = () => {
    setDarkMode((prev) => !prev);
    document.body.style.backgroundColor = darkMode ? "#fff" : "#1e293b";
    document.body.style.color = darkMode ? "#000" : "#fff";
  };

  const handleAutomateResolution = () => {
    alert("Automated resolution triggered!");
    // Add API call or logic for triggering automation
  };

  return (
    <div
      style={{
        padding: "2rem",
        backgroundColor: darkMode ? "#1e293b" : "#f8fafc",
        color: darkMode ? "#f8fafc" : "#1e293b",
        minHeight: "100vh",
      }}
    >
      {/* Navbar */}
      <nav
        style={{
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          padding: "1rem",
          marginBottom: "2rem",
          backgroundColor: darkMode ? "#2d3748" : "#e2e8f0",
          borderRadius: "8px",
          boxShadow: "0 2px 8px rgba(0, 0, 0, 0.1)",
        }}
      >
        <a
          href="/"
          style={{
            textDecoration: "none",
            color: darkMode ? "#f8fafc" : "#1e293b",
            margin: "0 1rem",
            fontWeight: "bold",
            fontSize: "1.1rem",
          }}
        >
          Home
        </a>
        <a
          href="/admin"
          style={{
            textDecoration: "none",
            color: darkMode ? "#f8fafc" : "#1e293b",
            margin: "0 1rem",
            fontWeight: "bold",
            fontSize: "1.1rem",
          }}
        >
          Admin
        </a>
        <a
          href="/user"
          style={{
            textDecoration: "none",
            color: darkMode ? "#f8fafc" : "#1e293b",
            margin: "0 1rem",
            fontWeight: "bold",
            fontSize: "1.1rem",
          }}
        >
          User
        </a>
        <a
          href="/login"
          style={{
            textDecoration: "none",
            color: darkMode ? "#f8fafc" : "#1e293b",
            margin: "0 1rem",
            fontWeight: "bold",
            fontSize: "1.1rem",
          }}
        >
          Login
        </a>
      </nav>

      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
        <h1>Admin Dashboard</h1>
        <button
          onClick={handleToggleDarkMode}
          style={{
            padding: "0.5rem 1rem",
            backgroundColor: darkMode ? "#f1c40f" : "#4caf50",
            color: "#fff",
            border: "none",
            borderRadius: "5px",
            cursor: "pointer",
          }}
        >
          Toggle {darkMode ? "Light" : "Dark"} Mode
        </button>
      </div>

      <div style={{ display: "flex", flexWrap: "wrap", gap: "2rem", marginTop: "2rem" }}>
        {/* Monitoring Widget */}
        <MonitoringWidget />

        {/* Machine Learning Widget */}
        <MLWidget />

        {/* Error Rates Widget */}
        <div
          style={{
            flex: "1",
            padding: "1.5rem",
            backgroundColor: darkMode ? "#2d3748" : "#fff",
            borderRadius: "8px",
            boxShadow: "0 2px 8px rgba(0, 0, 0, 0.1)",
          }}
        >
          <h3>Error Rates</h3>
          <p
            style={{
              fontSize: "1.5rem",
              fontWeight: "bold",
              color: darkMode ? "#f1c40f" : "#e74c3c",
            }}
          >
            {errorRate}
          </p>
        </div>

        {/* Server Logs Widget */}
        <div
          style={{
            flex: "1",
            padding: "1.5rem",
            backgroundColor: darkMode ? "#2d3748" : "#fff",
            borderRadius: "8px",
            boxShadow: "0 2px 8px rgba(0, 0, 0, 0.1)",
            overflowY: "auto",
            maxHeight: "200px",
          }}
        >
          <h3>Server Logs</h3>
          <ul style={{ listStyle: "none", padding: "0", margin: "0" }}>
            {serverLogs.map((log, index) => (
              <li key={index} style={{ marginBottom: "0.5rem" }}>
                - {log}
              </li>
            ))}
          </ul>
        </div>

        {/* Automated Resolution Widget */}
        <div
          style={{
            flex: "1",
            padding: "1.5rem",
            backgroundColor: darkMode ? "#2d3748" : "#fff",
            borderRadius: "8px",
            boxShadow: "0 2px 8px rgba(0, 0, 0, 0.1)",
            textAlign: "center",
          }}
        >
          <h3>Automated Resolution</h3>
          <button
            onClick={handleAutomateResolution}
            style={{
              padding: "0.75rem 1.5rem",
              backgroundColor: "#4caf50",
              color: "#fff",
              border: "none",
              borderRadius: "5px",
              cursor: "pointer",
              marginTop: "1rem",
            }}
          >
            Trigger Automation
          </button>
          <p style={{ marginTop: "1rem", fontSize: "0.9rem", color: darkMode ? "#f8fafc" : "#555" }}>
            This will automatically resolve common server issues, including:
          </p>
          <ul
            style={{
              listStyle: "disc",
              textAlign: "left",
              margin: "0.5rem 0 0 1rem",
              color: darkMode ? "#f8fafc" : "#555",
              fontSize: "0.9rem",
            }}
          >
            <li>Clearing cache</li>
            <li>Restarting affected services</li>
            <li>Freeing up memory</li>
            <li>Updating configuration files</li>
          </ul>
        </div>
      </div>
    </div>
  );
};

export default AdminDashboard;
